ST.xhtml:p:
IF bFast THEN
  DustAxisJog.Mode := 1;
ELSE
  DustAxisJog.Mode := 0;
END_IF;

DustAxisJog.JogForward := bDustAxisForward;
DustAxisJog.JogBackwards := bDustAxisBackward;

  (*防甩轴3=抽尘轴2*)
IF bFast THEN
  g_AntiRejection3Jog.Mode := 1;
ELSE
  g_AntiRejection3Jog.Mode := 0;
END_IF;

  g_AntiRejection3Jog.JogForward := bAntiRejection3Forward;
  g_AntiRejection3Jog.JogBackwards := bAntiRejection3Backward;



IF g_bPlcResetBuffer THEN
  bDustAxisForward := FALSE;
  bDustAxisBackward := FALSE;
  bAntiRejection3Forward := FALSE;
  bAntiRejection3Backward := FALSE;
END_IF;
